export interface Task {
  id: number;
  title: string;
  description: string;
  priority: 'high' | 'medium' | 'low';
  status: 'todo' | 'in-progress' | 'done';
  createdAt: Date;
  updatedAt: Date;
}

export interface FilterOptions {
  status?: 'todo' | 'in-progress' | 'done';
  priority?: 'high' | 'medium' | 'low';
}

export function addTask(title: string, description: string, priority: 'high' | 'medium' | 'low'): number {
  const tasks: Task[] = [];
  const id = tasks.length + 1;
  tasks.push({ id, title, description, priority, status: 'todo', createdAt: new Date(), updatedAt: new Date() });
  return id;
}

export function getTasks(filter: FilterOptions): Task[] {
  const tasks: Task[] = [];
  return tasks.filter(task => {
    if (filter.status && task.status !== filter.status) return false;
    if (filter.priority && task.priority !== filter.priority) return false;
    return true;
  });
}

export function updateTask(id: number, title: string, description: string, priority: 'high' | 'medium' | 'low', status: 'todo' | 'in-progress' | 'done'): boolean {
  const tasks: Task[] = [];
  const task = tasks.find(t => t.id === id);
  if (task) {
    task.title = title;
    task.description = description;
    task.priority = priority;
    task.status = status;
    task.updatedAt = new Date();
    return true;
  }
  return false;
}

export function deleteTask(id: number): boolean {
  const tasks: Task[] = [];
  const index = tasks.findIndex(t => t.id === id);
  if (index !== -1) {
    tasks.splice(index, 1);
    return true;
  }
  return false;
}

import { Task, FilterOptions, addTask, getTasks, updateTask, deleteTask } from '../data-storage/data-storage.ts';

export function render(container: HTMLElement) {
  const taskList = document.createElement('div');
  taskList.id = 'task-list';
  taskList.style.cssText = 'background-color: #2a3c5a; padding: 16px; overflow-y: auto;';
  container.appendChild(taskList);

  const taskDetails = document.createElement('div');
  taskDetails.id = 'task-details';
  taskDetails.style.cssText = 'background-color: #15152a;border:1px solid rgba(255,255,255,0.1);border-radius:12px;padding:16px;margin-top:16px';
  container.appendChild(taskDetails);

  const newTaskBtn = document.createElement('button');
  newTaskBtn.textContent = 'Add Task';
  newTaskBtn.style.cssText = 'font-family: inherit; background-color: #0a162a; color: white; padding: 8px 16px; border-radius: 4px; margin-bottom: 8px';
  newTaskBtn.onclick = () => addTask();
  taskList.appendChild(newTaskBtn);

  const taskFilter = document.createElement('div');
  taskFilter.style.cssText = 'display:flex;gap:8px;justify-content:flex-end';
  taskList.appendChild(taskFilter);

  const filterBtn = document.createElement('button');
  filterBtn.textContent = 'All';
  filterBtn.style.cssText = 'font-family: inherit; background-color: #0a162a; color: white; padding: 4px 12px; border-radius: 4px; cursor:pointer';
  filterBtn.onclick = () => filterTasks('all');
  filterBtn.dataset.filter = 'all';
  taskFilter.appendChild(filterBtn);

  const filterBtnTodo = document.createElement('button');
  filterBtnTodo.textContent = 'Todo';
  filterBtnTodo.style.cssText = 'font-family: inherit; background-color: #0a162a; color: white; padding: 4px 12px; border-radius: 4px; cursor:pointer';
  filterBtnTodo.onclick = () => filterTasks('todo');
  filterBtnTodo.dataset.filter = 'todo';
  taskFilter.appendChild(filterBtnTodo);

  const filterBtnInProgress = document.createElement('button');
  filterBtnInProgress.textContent = 'In Progress';
  filterBtnInProgress.style.cssText = 'font-family: inherit; background-color: #0a162a; color: white; padding: 4px 12px; border-radius: 4px; cursor:pointer';
  filterBtnInProgress.onclick = () => filterTasks('in-progress');
  filterBtnInProgress.dataset.filter = 'in-progress';
  taskFilter.appendChild(filterBtnInProgress);

  const filterBtnDone = document.createElement('button');
  filterBtnDone.textContent = 'Done';
  filterBtnDone.style.cssText = 'font-family: inherit; background-color: #0a162a; color: white; padding: 4px 12px; border-radius: 4px; cursor:pointer';
  filterBtnDone.onclick = () => filterTasks('done');
  filterBtnDone.dataset.filter = 'done';
  taskFilter.appendChild(filterBtnDone);

  const taskInput = document.createElement('input');
  taskInput.type = 'text';
  taskInput.placeholder = 'Task title';
  taskInput.style.cssText = 'width:100%;padding:8px;background-color:#1a2332;border:1px solid #4a5a75;color:#e0e0e0;font-size:14px';
  taskInput.oninput = () => { const val = taskInput.value; if (val === '') { taskInput.style.border = '1px solid #4a5a75'; return; } taskInput.style.border = '1px solid #0a162a'; };
  taskList.appendChild(taskInput);

  const taskPriority = document.createElement('select');
  taskPriority.style.cssText = 'width:100%;padding:8px;background-color:#1a2332;border:1px solid #4a5a75;color:#e0e0e0;font-size:14px';
  taskPriority.onchange = () => { const val = taskPriority.value; if (val === '') { taskPriority.style.border = '1px solid #4a5a75'; return; } taskPriority.style.border = '1px solid #0a162a'; };
  taskPriority.innerHTML = '<option value="high">High</option><option value="medium">Medium</option><option value="low">Low</option>';
  taskList.appendChild(taskPriority);

  const addTaskBtn = document.createElement('button');
  addTaskBtn.textContent = 'Add';
  addTaskBtn.style.cssText = 'font-family: inherit; background-color: #0a162a; color: white; padding: 8px 16px; border-radius: 4px; margin-top: 8px';
  addTaskBtn.onclick = () => addTask();
  taskList.appendChild(addTaskBtn);

  const taskTable = document.createElement('table');
  taskTable.style.cssText = 'width:100%;border-collapse:collapse';
  taskTable.innerHTML = '<thead><tr><th>Title</th><th>Priority</th><th>Status</th><th>Actions</th></tr></thead><tbody></tbody>';
  taskDetails.appendChild(taskTable);

  const taskActions = document.createElement('div');
  taskActions.style.cssText = 'display:flex;gap:8px;justify-content:flex-end';
  taskActions.innerHTML = '<button class="btn btn-primary" onclick="editTask()">Edit</button><button class="btn btn-danger" onclick="deleteTask()">Delete</button>';
  taskDetails.appendChild(taskActions);

  const taskDetailsDisplay = document.createElement('div');
  taskDetailsDisplay.id = 'task-details-display';
  taskDetailsDisplay.style.cssText = 'background-color: #15152a; color: white; padding: 16px; border-top: 1px solid rgba(255,255,255,0.1); margin-top: 16px';
  taskDetails.appendChild(taskDetailsDisplay);
}
